        const [min, max] = searchAgeRange.split('-').map(Number);
        if (!isNaN(min) && !isNaN(max)) {
          filtered = filtered.filter(m => m.age >= min && m.age <= max);
        }
      }

      if (searchTown && searchTown.trim() !== '') {
        const townLower = searchTown.toLowerCase().trim();
        filtered = filtered.filter(m => 
          m.town.toLowerCase().includes(townLower)
        );
      }

      if (searchCounty && searchCounty.trim() !== '') {
        const countyLower = searchCounty.toLowerCase().trim();
        filtered = filtered.filter(m => 
          m.county && m.county.toLowerCase().includes(countyLower)
        );
